/usr/bin/bash -lc "node --input-type=module <<'EOF'
import assert from 'node:assert/strict';
import { createTransferWorkspace, createProgressFeed, collectProgressTelemetry } from './src/workspace.js';
const records=[], history=[], shown=[], deltas=[], cancels=[];
const pending=new Map();
const feed=createProgressFeed({initialPacket:'initial',decode:p=>p.startsWith('async')?new Promise(resolve=>pending.set(p,resolve)):p});
const stopTelemetry=collectProgressTelemetry(feed,f=>deltas.push(f));
const ws=createTransferWorkspace({transport(){},onCancel:x=>cancels.push(x.attemptId),record:x=>records.push(x),showQueued(){},recordProgress:x=>history.push(x),showProgress:x=>shown.push(x)});
const file={id:'f',progressFeed:feed};
ws.select(file);
assert.deepEqual(shown.map(x=>x.frame),['initial']);
assert.deepEqual(deltas,[]);
feed.emit('async-old'); feed.emit('async-new');
pending.get('async-new')('new'); await Promise.resolve();
pending.get('async-old')('old'); await Promise.resolve();
assert.deepEqual(shown.map(x=>x.frame),['initial','new']);
assert.deepEqual(history.map(x=>x.frame),['initial','new','old']);
ws.retry();
assert.deepEqual(shown.map(x=>x.frame),['initial','new','initial']);
ws.hide(); ws.select(file);
assert.equal(shown.at(-1).frame,'initial');
ws.dispose(); stopTelemetry();
assert.equal(cancels.length,3);
assert.deepEqual(records.map(x=>x.kind),['select','retry','select']);
console.log('progress lifecycle checks passed');
EOF"

